package com.shopsphere.controller;
import com.shopsphere.model.User; import com.shopsphere.util.DB; import jakarta.servlet.*; import jakarta.servlet.http.*; import jakarta.servlet.annotation.*; import java.io.IOException; import java.sql.*;
@WebServlet("/cart") public class CartServlet extends HttpServlet {
 protected void doGet(HttpServletRequest q,HttpServletResponse p)throws ServletException,IOException{User u=(User)q.getSession().getAttribute("user");try(Connection c=DB.getConnection();PreparedStatement s=c.prepareStatement("SELECT p.product_id,p.name,p.price,p.discount,p.image_url,c.quantity,p.stock FROM cart c JOIN products p ON p.product_id=c.product_id WHERE c.user_id=? AND p.status=TRUE")){s.setLong(1,u.getUserId());try(ResultSet r=s.executeQuery()){java.util.List<java.util.Map<String,Object>> items=new java.util.ArrayList<>();java.math.BigDecimal total=java.math.BigDecimal.ZERO;while(r.next()){java.math.BigDecimal price=r.getBigDecimal("price").multiply(java.math.BigDecimal.ONE.subtract(r.getBigDecimal("discount").divide(new java.math.BigDecimal("100")))).setScale(2,java.math.RoundingMode.HALF_UP);java.util.Map<String,Object> m=new java.util.HashMap<>();m.put("id",r.getLong("product_id"));m.put("name",r.getString("name"));m.put("price",price);m.put("quantity",r.getInt("quantity"));m.put("stock",r.getInt("stock"));m.put("lineTotal",price.multiply(java.math.BigDecimal.valueOf(r.getInt("quantity"))));items.add(m);total=total.add((java.math.BigDecimal)m.get("lineTotal"));}q.setAttribute("items",items);q.setAttribute("total",total);}q.getRequestDispatcher("/WEB-INF/views/cart.jsp").forward(q,p);}catch(Exception e){throw new ServletException("Could not load cart",e);}}
 protected void doPost(HttpServletRequest q,HttpServletResponse p)throws ServletException,IOException{User u=(User)q.getSession().getAttribute("user");String action=q.getParameter("action");try(Connection c=DB.getConnection()){long id=Long.parseLong(q.getParameter("productId"));if("remove".equals(action)){try(PreparedStatement s=c.prepareStatement("DELETE FROM cart WHERE user_id=? AND product_id=?")){s.setLong(1,u.getUserId());s.setLong(2,id);s.executeUpdate();}}else{int qty=1;try{qty=Integer.parseInt(q.getParameter("quantity"));}catch(Exception ignored){}if(qty<1||qty>99)throw new IllegalArgumentException("Quantity must be from 1 to 99.");try(PreparedStatement check=c.prepareStatement("SELECT stock FROM products WHERE product_id=? AND status=TRUE")){check.setLong(1,id);try(ResultSet r=check.executeQuery()){if(!r.next()||r.getInt(1)<qty)throw new IllegalArgumentException("Product is unavailable or stock is insufficient.");}}try(PreparedStatement s=c.prepareStatement("INSERT INTO cart(user_id,product_id,quantity) VALUES(?,?,?) ON DUPLICATE KEY UPDATE quantity=LEAST(quantity+VALUES(quantity),99)")){s.setLong(1,u.getUserId());s.setLong(2,id);s.setInt(3,qty);s.executeUpdate();}}p.sendRedirect(q.getContextPath()+"/cart");}catch(IllegalArgumentException e){p.sendRedirect(q.getContextPath()+"/products?error=Invalid+product+or+quantity");}catch(Exception e){throw new ServletException("Could not update cart",e);}}
}
